import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.q07Y7wJQ.js";var i=JSON.parse(`{"title":"Frequently Asked Questions (FAQ)","description":"","frontmatter":{"prev":{"text":"Browser Bus","link":"/documentation/browser-bus"}},"headers":[],"relativePath":"documentation/question-answer/question-answer.md","filePath":"documentation/question-answer/question-answer.md","lastUpdated":1788551488000}`),a={name:`documentation/question-answer/question-answer.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="faq" tabindex="-1">Frequently Asked Questions (FAQ) <a class="header-anchor" href="#faq" aria-label="Permalink to “Frequently Asked Questions (FAQ)”">​</a></h1><p>Find answers to common questions about installing, configuring, automating, and troubleshooting Excellent Data Filler V4.</p><hr><h2 id="general-overview" tabindex="-1">General Overview <a class="header-anchor" href="#general-overview" aria-label="Permalink to “General Overview”">​</a></h2><h3 id="what-is-excellent-data-filler" tabindex="-1">What is Excellent Data Filler? <a class="header-anchor" href="#what-is-excellent-data-filler" aria-label="Permalink to “What is Excellent Data Filler?”">​</a></h3><p><strong>Excellent Data Filler</strong> is an enterprise-grade browser extension designed for automated web form filling, data scraping, and workflow automation across modern web browsers. It eliminates repetitive manual data entry by extracting records from spreadsheets or APIs and accurately populating complex web forms with granular timing delays, custom validations, and conditional logic.</p><h3 id="which-browsers-are-supported-and-how-do-i-install-it" tabindex="-1">Which browsers are supported, and how do I install it? <a class="header-anchor" href="#which-browsers-are-supported-and-how-do-i-install-it" aria-label="Permalink to “Which browsers are supported, and how do I install it?”">​</a></h3><p>Excellent Data Filler is available on both Chrome Web Store and Firefox Add-ons, and works across all major Chromium and Gecko browsers:</p><table tabindex="0"><thead><tr><th>Browser</th><th>Installation Source</th><th>Direct Link</th></tr></thead><tbody><tr><td><strong>Google Chrome</strong></td><td>Chrome Web Store</td><td><a href="https://chrome.google.com/webstore/detail/excellent-data-filler-cth/abafaagbfhobgjkcepckbnadafflkdea" target="_blank" rel="noreferrer">Install for Chrome</a></td></tr><tr><td><strong>Mozilla Firefox</strong></td><td>Firefox Add-ons</td><td><a href="https://addons.mozilla.org/en-US/firefox/addon/excellent-data-filler/" target="_blank" rel="noreferrer">Install for Firefox</a></td></tr><tr><td><strong>Microsoft Edge</strong></td><td>Chrome Web Store</td><td><a href="https://chrome.google.com/webstore/detail/excellent-data-filler-cth/abafaagbfhobgjkcepckbnadafflkdea" target="_blank" rel="noreferrer">Install for Edge</a></td></tr><tr><td><strong>Brave / Opera / Vivaldi</strong></td><td>Chrome Web Store</td><td><a href="https://chrome.google.com/webstore/detail/excellent-data-filler-cth/abafaagbfhobgjkcepckbnadafflkdea" target="_blank" rel="noreferrer">Install for Chromium</a></td></tr></tbody></table><p><strong>Installation Steps:</strong></p><ol><li>Open the installation link for your browser above.</li><li>Click <strong>Add to Chrome</strong> (or <strong>Add to Firefox</strong>).</li><li>Confirm permissions in the browser prompt.</li><li>Pin the extension icon to your browser toolbar for quick access.</li></ol><h3 id="what-makes-excellent-data-filler-different-from-basic-autofill-tools" tabindex="-1">What makes Excellent Data Filler different from basic autofill tools? <a class="header-anchor" href="#what-makes-excellent-data-filler-different-from-basic-autofill-tools" aria-label="Permalink to “What makes Excellent Data Filler different from basic autofill tools?”">​</a></h3><p>Unlike simple password or profile autofill tools, Excellent Data Filler provides:</p><ul><li><strong>Full Spreadsheet Integration</strong>: Feed dynamic rows from local <code>.xlsx</code> files or real-time Google Sheets.</li><li><strong>Complex UI Control</strong>: Supports standard inputs, textareas, native select dropdowns, Material UI search-and-select menus, radio groups, checkboxes, custom click triggers, and date pickers.</li><li><strong>Multi-Step Workflows</strong>: Automate multi-page wizard forms and re-usable on-demand routines with <a href="/documentation/segment.html">Segments</a>.</li><li><strong>Embedded Web Scraping</strong>: Extract confirmation numbers, generated IDs, and table data back into <code>.xlsx</code> reports with <a href="/documentation/site/site-scraper-data.html">Scraper Data</a>.</li><li><strong>Custom Scripting</strong>: Run isolated JavaScript code directly within the page context.</li></ul><hr><h2 id="getting-started" tabindex="-1">Getting Started &amp; Workflow <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting Started &amp; Workflow”">​</a></h2><h3 id="how-do-i-automate-my-first-form" tabindex="-1">How do I automate my first form? <a class="header-anchor" href="#how-do-i-automate-my-first-form" aria-label="Permalink to “How do I automate my first form?”">​</a></h3><p>Follow these core steps:</p><ol><li><strong>Register the Site</strong>: <ul><li>Navigate to your target web form.</li><li>Press <kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>S</kbd> or right-click the page and choose <strong>Insert Site</strong>.</li></ul></li><li><strong>Add Fields</strong>: <ul><li>Press <kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>I</kbd> on any input element to open the <strong>DOM Element Inspector</strong>.</li><li>Copy or assign the CSS Selector / XPath to your form configuration.</li></ul></li><li><strong>Attach Data</strong>: <ul><li>Download the pre-built template via <strong>Download Excel Template</strong>.</li><li>Populate your records in <code>.xlsx</code> format and upload it back, or connect a Google Sheet.</li></ul></li><li><strong>Run Automation</strong>: <ul><li>Trigger execution with <kbd>Alt</kbd> + <kbd>Q</kbd> or simply refresh the page when the extension is ON.</li></ul></li></ol><h3 id="what-is-the-difference-between-a-site-a-form-and-a-segment" tabindex="-1">What is the difference between a Site, a Form, and a Segment? <a class="header-anchor" href="#what-is-the-difference-between-a-site-a-form-and-a-segment" aria-label="Permalink to “What is the difference between a Site, a Form, and a Segment?”">​</a></h3><ul><li><strong>Site</strong>: The top-level domain or project container holding forms, data sources, segments, and site-wide settings.</li><li><strong>Site Form</strong>: A URL-specific automation routine that runs automatically when a matching web page loads.</li><li><strong>Segment</strong>: An on-demand, modular routine of fields that can be triggered programmatically, across pages, or executed repeatedly in loops.</li></ul><hr><h2 id="data-sources" tabindex="-1">Data Sources &amp; Spreadsheets <a class="header-anchor" href="#data-sources" aria-label="Permalink to “Data Sources &amp; Spreadsheets”">​</a></h2><h3 id="which-spreadsheet-formats-are-supported-for-upload" tabindex="-1">Which spreadsheet formats are supported for upload? <a class="header-anchor" href="#which-spreadsheet-formats-are-supported-for-upload" aria-label="Permalink to “Which spreadsheet formats are supported for upload?”">​</a></h3><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Strict <code>.xlsx</code> Support</strong>: Excellent Data Filler exclusively supports Microsoft Excel (<code>.xlsx</code>) files for local spreadsheet data uploads. Other formats such as <code>.csv</code> or <code>.xls</code> are not supported.</p></div><p>You can also connect cloud spreadsheets directly using <strong>Google Sheets (Beta)</strong> via OAuth2 or a Google Cloud Service Account JSON key.</p><h3 id="how-does-google-sheets-beta-integration-work" tabindex="-1">How does Google Sheets (Beta) integration work? <a class="header-anchor" href="#how-does-google-sheets-beta-integration-work" aria-label="Permalink to “How does Google Sheets (Beta) integration work?”">​</a></h3><p>Google Sheets integration allows real-time cloud data access without manual file uploads:</p><ol><li>In your Site workspace, open the <strong>Upload Excel</strong> tab and choose <strong>Google Sheet (Beta)</strong>.</li><li>Authenticate using either: <ul><li><strong>OAuth2 (Login Required)</strong>: Sign in with your Google account.</li><li><strong>Client Service Account (No Login Required)</strong>: Upload a GCP Service Account JSON key file and share your sheet with the service account email.</li></ul></li><li>Paste the Spreadsheet URL and Sheet Tab Name.</li><li>Click <strong>Update Sheet With Site Data</strong> to automatically synchronize field headers with sheet columns.</li><li>If you edit cell values in Google Sheets, click <strong>Clear Sheet Cache</strong> to fetch fresh records.</li></ol><h3 id="how-can-i-distribute-data-rows-across-multiple-browsers" tabindex="-1">How can I distribute data rows across multiple browsers? <a class="header-anchor" href="#how-can-i-distribute-data-rows-across-multiple-browsers" aria-label="Permalink to “How can I distribute data rows across multiple browsers?”">​</a></h3><p>Use the <strong>Browser ID</strong> feature in Google Sheets:</p><ol><li>Toggle <strong>Fetch Sheet Row Data Using Browser Id</strong> in the Google Sheet configuration.</li><li>Enter your assigned browser identifier (e.g., <code>browser-1</code>).</li><li>Add a column named <code>&lt;code v-pre&gt;{BROWSER-ID}&lt;/code&gt;</code> to your Google Sheet.</li><li>Assign corresponding browser IDs to your data rows. Each browser instance will only process rows matching its assigned ID.</li></ol><hr><h2 id="shortcuts-controls" tabindex="-1">Keyboard Shortcuts &amp; Controls <a class="header-anchor" href="#shortcuts-controls" aria-label="Permalink to “Keyboard Shortcuts &amp; Controls”">​</a></h2><h3 id="what-are-the-default-keyboard-shortcuts" tabindex="-1">What are the default keyboard shortcuts? <a class="header-anchor" href="#what-are-the-default-keyboard-shortcuts" aria-label="Permalink to “What are the default keyboard shortcuts?”">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th><th>Description</th></tr></thead><tbody><tr><td><strong>Start / Pause Automation</strong></td><td><kbd>Alt</kbd> + <kbd>Q</kbd></td><td>Starts or pauses current form automation</td></tr><tr><td><strong>Inspect Elements</strong></td><td><kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>I</kbd></td><td>Opens DOM element selector inspector</td></tr><tr><td><strong>Insert Site</strong></td><td><kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>S</kbd></td><td>Registers a new site from the active page</td></tr><tr><td><strong>Insert Form</strong></td><td><kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>F</kbd></td><td>Adds a new form to the active site</td></tr><tr><td><strong>Copy Field</strong></td><td><kbd>Alt</kbd> + <kbd>C</kbd></td><td>Copies selected field configuration</td></tr><tr><td><strong>Copy Form Response</strong></td><td><kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>R</kbd></td><td>Copies element text, selector, XPath, and URL</td></tr><tr><td><strong>Copy Element Selector</strong></td><td><kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>C</kbd></td><td>Copies CSS selector of selected element</td></tr><tr><td><strong>Copy Element XPath</strong></td><td><kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>X</kbd></td><td>Copies XPath of selected element</td></tr><tr><td><strong>Copy Element Text</strong></td><td><kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>T</kbd></td><td>Copies text content of selected element</td></tr><tr><td><strong>Copy Element HTML</strong></td><td><kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>H</kbd></td><td>Copies HTML markup of selected element</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Shortcuts can be customized in your browser at <code>chrome://extensions/shortcuts</code>. Note that <kbd>Alt</kbd> + <kbd>F</kbd> does not exist in this extension.</p></div><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting &amp; Diagnostics <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting &amp; Diagnostics”">​</a></h2><h3 id="why-is-data-not-filling-into-my-form" tabindex="-1">Why is data not filling into my form? <a class="header-anchor" href="#why-is-data-not-filling-into-my-form" aria-label="Permalink to “Why is data not filling into my form?”">​</a></h3><p>If automation does not trigger or skip inputs, check the following:</p><ol><li><strong>Extension Status</strong>: Verify that the extension is toggled <strong>ON</strong> in the popup toolbar.</li><li><strong>URL Matching</strong>: Check if the target page URL matches the Form URL rule (ensure regex matches query parameters if the URL is dynamic).</li><li><strong>Element Selectors</strong>: Inspect the input using <kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>I</kbd>. Dynamic web frameworks often randomize IDs (e.g., <code>id=&quot;input-8472&quot;</code>), requiring you to use stable attributes like <code>name=&quot;email&quot;</code> or <code>input[type=&quot;email&quot;]</code>.</li><li><strong>Timing Delays</strong>: If elements render asynchronously, add a delay in <strong>Delay Time Before Running This Field</strong> (e.g., <code>500ms</code> or <code>1500ms</code>).</li><li><strong>Execution Logs</strong>: Open the extension <a href="/documentation/logs.html">Logs</a> dashboard to see exact error messages, missing column notices, or unlocated selectors.</li></ol><h3 id="what-should-i-do-if-a-web-page-disables-right-clicking" tabindex="-1">What should I do if a web page disables right-clicking? <a class="header-anchor" href="#what-should-i-do-if-a-web-page-disables-right-clicking" aria-label="Permalink to “What should I do if a web page disables right-clicking?”">​</a></h3><p>Some websites block context menus via JavaScript. To enable the context menu:</p><ol><li>Open the extension <strong>Settings</strong> tab.</li><li>Toggle ON <strong>Allow Right Click?</strong>.</li><li>Alternatively, use keyboard shortcuts directly: <ul><li><kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>S</kbd> to insert the site.</li><li><kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>I</kbd> to inspect elements.</li></ul></li></ol><h3 id="how-do-i-scrape-data-from-a-web-page" tabindex="-1">How do I scrape data from a web page? <a class="header-anchor" href="#how-do-i-scrape-data-from-a-web-page" aria-label="Permalink to “How do I scrape data from a web page?”">​</a></h3><ol><li>Add a field to your Form or Segment with a scraper field type (e.g., text scraper, table scraper).</li><li>Set the CSS selector or XPath pointing to the data you want to harvest.</li><li>Run the automation workflow.</li><li>Navigate to the <strong>Scraper Data</strong> tab under your Site workspace and download your results as a multi-sheet or single-sheet <code>.xlsx</code> workbook.</li></ol><hr><h2 id="community-support" tabindex="-1">Community &amp; Support Channels <a class="header-anchor" href="#community-support" aria-label="Permalink to “Community &amp; Support Channels”">​</a></h2><p>Need assistance, want to suggest a feature, or looking for video walkthroughs?</p><ul><li><img src="/svg/book.svg" class="doc-icon"> <a href="/documentation/">Documentation Portal</a> - Complete guides, field types, and architecture walkthroughs</li><li><img src="/svg/youtube.svg" class="doc-icon"> <a href="https://www.youtube.com/@ctechhindi" target="_blank" rel="noreferrer">YouTube Channel (C Tech Hindi)</a> - Video tutorials and walkthrough guides</li><li><img src="/svg/chat.svg" class="doc-icon"> <a href="https://groups.google.com/g/excellent-data-filler" target="_blank" rel="noreferrer">Google Group Community</a> - User discussions, tips, and troubleshooting</li><li><img src="/svg/whatsapp.svg" class="doc-icon"> <a href="https://chat.whatsapp.com/F2AdHoZRvr8HiAbvWqKlVS" target="_blank" rel="noreferrer">WhatsApp Group</a> - Community chat and real-time support</li><li><img src="/svg/bug.svg" class="doc-icon"> <a href="https://github.com/jeevan-lal/excellent-data-filler-docs/issues" target="_blank" rel="noreferrer">GitHub Issues</a> - Bug reports and technical issue tracking</li></ul>`,51)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};